window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["aurora"]={html:"<div class=\"own-aurora\">\n  <div class=\"au-topbar\">\n    <a class=\"au-brand\" href=\"#au-top\" aria-label=\"Northwind home\">\n      <span class=\"au-mark\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"9\" width=\"3\" height=\"6\" rx=\"1.5\"/><rect x=\"8.5\" y=\"6\" width=\"3\" height=\"12\" rx=\"1.5\"/><rect x=\"14\" y=\"8\" width=\"3\" height=\"8\" rx=\"1.5\"/><rect x=\"19.5\" y=\"4.5\" width=\"3\" height=\"15\" rx=\"1.5\"/></svg>\n      </span>\n      <span class=\"au-brand-text\"><b>Northwind</b><em>Operations Insights</em></span>\n    </a>\n    <nav class=\"au-navbar\" aria-label=\"Primary\">\n      <a class=\"au-nav-item on\" href=\"#au-tabs\"><span class=\"au-dot\"></span>Pulse</a>\n      <a class=\"au-nav-item\" href=\"#au-tabs\"><span class=\"au-dot\"></span>Regions</a>\n      <a class=\"au-nav-item\" href=\"#au-tabs\"><span class=\"au-dot\"></span>Forecast</a>\n      <span class=\"au-nav-spacer\"></span>\n      <span class=\"au-chip\">This quarter</span>\n      <button class=\"au-btn au-btn-dark\" type=\"button\">Filters</button>\n      <button class=\"au-identity\" type=\"button\" aria-label=\"Account menu\">\n        <span class=\"au-identity-av\">FL</span>\n        <span class=\"au-identity-text\"><b>Ferdz Lopez</b><em>Ops lead · 28 sites</em></span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m6 9 6 6 6-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>\n      </button>\n    </nav>\n  </div>\n\n  <main id=\"au-top\">\n    <section class=\"au-hero\" aria-labelledby=\"au-h1\">\n      <div class=\"au-aurora\" aria-hidden=\"true\"></div>\n      <div class=\"au-hero-copy\">\n        <p class=\"au-eyebrow\">Operations digest · Thursday 08 Oct</p>\n        <div class=\"au-metric\">\n          <span class=\"au-metric-num\">98.1<span class=\"au-metric-unit\">%</span></span>\n          <span class=\"au-delta\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m12 5 7 9H5z\"/></svg>\n            9.9 vs yesterday\n          </span>\n        </div>\n        <h1 id=\"au-h1\" class=\"au-h1\">Network <span class=\"au-accent\">throughput</span> is holding above goal</h1>\n        <p class=\"au-brief\">Twelve regions on one governed model. Line yield, cost per unit, and fulfilment settle against the same source — no export, no stale mirror.</p>\n        <div class=\"au-hero-cta\">\n          <a class=\"au-btn au-btn-dark\" href=\"#au-tabs\">Open the wall</a>\n          <a class=\"au-btn au-btn-ghost\" href=\"#au-tabs\">Share digest</a>\n        </div>\n      </div>\n      <div class=\"au-card au-trend\">\n        <div class=\"au-trend-head\">\n          <div><p class=\"au-card-title\">Daily network PTG</p><p class=\"au-card-sub\">14-day rolling</p></div>\n          <span class=\"au-chip au-chip-fill\">Peak 104.7</span>\n        </div>\n        <svg class=\"au-chart\" viewBox=\"0 0 420 150\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n          <defs>\n            <linearGradient id=\"auLg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n              <stop offset=\"0%\" stop-color=\"#E0714A\"/><stop offset=\"52%\" stop-color=\"#FFE24A\"/><stop offset=\"100%\" stop-color=\"#3FBF7A\"/>\n            </linearGradient>\n            <linearGradient id=\"auAg\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n              <stop offset=\"0%\" stop-color=\"#9BF1B4\" stop-opacity=\".55\"/><stop offset=\"100%\" stop-color=\"#9BF1B4\" stop-opacity=\"0\"/>\n            </linearGradient>\n          </defs>\n          <path d=\"M0,96 C40,80 60,104 100,92 C140,80 160,58 200,64 C240,70 260,44 300,40 C340,36 380,24 420,20 L420,150 L0,150 Z\" fill=\"url(#auAg)\"/>\n          <path d=\"M0,96 C40,80 60,104 100,92 C140,80 160,58 200,64 C240,70 260,44 300,40 C340,36 380,24 420,20\" fill=\"none\" stroke=\"url(#auLg)\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n          <circle cx=\"420\" cy=\"20\" r=\"5\" fill=\"#3FBF7A\"/>\n        </svg>\n        <div class=\"au-legend\"><span class=\"au-legend-key\">D-13</span><span class=\"au-legend-key\">D-7</span><span class=\"au-legend-key\">Today</span></div>\n      </div>\n    </section>\n\n    <section id=\"au-tabs\" class=\"au-tabs\" aria-labelledby=\"au-tabs-h\">\n      <h2 id=\"au-tabs-h\" class=\"au-sr\">Network performance</h2>\n      <div class=\"au-tabrow\" id=\"auTabrow\">\n        <span class=\"au-strip\" aria-hidden=\"true\"></span>\n        <button class=\"au-tab on\" type=\"button\" data-tab=\"wall\" aria-pressed=\"true\"><span class=\"au-dot\"></span>Pulse wall</button>\n        <button class=\"au-tab\" type=\"button\" data-tab=\"board\" aria-pressed=\"false\"><span class=\"au-dot\"></span>Leaderboard</button>\n        <button class=\"au-tab\" type=\"button\" data-tab=\"city\" aria-pressed=\"false\"><span class=\"au-dot\"></span>By city</button>\n      </div>\n\n      <div class=\"au-panel\">\n        <div class=\"au-view\" data-view=\"wall\">\n          <div class=\"au-wall-head\"><span>Metric</span><span>14-day</span><span>Today</span><span>vs goal</span></div>\n          <div class=\"au-wall\" id=\"auWall\"></div>\n        </div>\n        <div class=\"au-view\" data-view=\"board\" hidden>\n          <div class=\"au-board-head\"><span>#</span><span>Region</span><span>Progress</span><span>PTG</span><span>Q</span></div>\n          <div class=\"au-board\" id=\"auBoard\"></div>\n        </div>\n        <div class=\"au-view\" data-view=\"city\" hidden>\n          <div class=\"au-city-head\"><span>City</span><span>Progress</span><span>PTG</span><span>n</span></div>\n          <div class=\"au-city\" id=\"auCity\"></div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"au-regions\" aria-labelledby=\"au-regions-h\">\n      <h2 id=\"au-regions-h\" class=\"au-panel-title\">Regions on the wall</h2>\n      <div class=\"au-region-grid\" id=\"auRegions\"></div>\n    </section>\n\n    <section class=\"au-note-band\" aria-labelledby=\"au-note-h\">\n      <div class=\"au-note-card\">\n        <p class=\"au-card-title\" id=\"au-note-h\">Where the model runs</p>\n        <p class=\"au-footnote\">Northwind resolves every region against one governed operations model. Guardrails flag a line the moment it drifts below grade, and a scheduled digest lands on the ops desk before each shift handover.</p>\n      </div>\n      <div class=\"au-note-stats\">\n        <div class=\"au-note-stat\"><b>12</b><span>regions</span></div>\n        <div class=\"au-note-stat\"><b>14</b><span>lines</span></div>\n        <div class=\"au-note-stat\"><b>$429M</b><span>recovered</span></div>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"au-footer\">\n    <div class=\"au-footer-brand\">\n      <span class=\"au-mark au-mark-lg\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"9\" width=\"3\" height=\"6\" rx=\"1.5\"/><rect x=\"8.5\" y=\"6\" width=\"3\" height=\"12\" rx=\"1.5\"/><rect x=\"14\" y=\"8\" width=\"3\" height=\"8\" rx=\"1.5\"/><rect x=\"19.5\" y=\"4.5\" width=\"3\" height=\"15\" rx=\"1.5\"/></svg>\n      </span>\n      <div><b>Northwind</b><p class=\"au-footnote\">Operations analytics — sample data, showcase only.</p></div>\n    </div>\n    <nav class=\"au-footer-links\" aria-label=\"Footer\">\n      <a href=\"#\">Boards</a><a href=\"#\">Regions</a><a href=\"#\">Guardrails</a><a href=\"#\">Digest</a>\n    </nav>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Aurora design language, for showcase.html ══════════\n   Light-only glass system: near-white canvas, blurred multi-radial aurora mesh,\n   floating pill navbar with the brand lockup OUTSIDE the pill, oversized\n   200-weight uppercase hero, glass cards, and the folder-tab component whose\n   active tab flares seamlessly into the panel below. Bright brand fills\n   (yellow/mint/pale-blue) are fill-only; text routes through derived inks. */\n\n.own-aurora {\n  --yellow: #FFFF7F;\n  --mint: #9BF1B4;\n  --pale-blue: #98C5D1;\n  --slate: #748C96;\n  --deep-slate: #425459;\n  --mint-ink: #1C7A4B;\n  --amber-ink: #8A6A08;\n  --coral: #E0714A;\n  --coral-ink: #B4502A;\n  --on-mint-fill: #12351F;\n  --bar-fill-green: #4FD08A;\n  --accent-dot-green: #3FBF7A;\n  --amber-bar-fill: #F2D93B;\n  --heatmap-amber: #FFE24A;\n  --canvas: #F6FAF8;\n  --card: rgba(255, 255, 255, .82);\n  --card-2: #FFFFFF;\n  --line: rgba(66, 84, 89, .13);\n  --line-2: rgba(66, 84, 89, .07);\n  --progress-track: rgba(66, 84, 89, .09);\n  --t0: #2B393D;\n  --t1: #425459;\n  --t2: #65787E;\n  --t3: #748C96;\n  --shadow: 0 1px 2px rgba(66, 84, 89, .05), 0 12px 32px -12px rgba(66, 84, 89, .16);\n  --shadow-menu: 0 2px 4px rgba(66, 84, 89, .06), 0 24px 48px -16px rgba(66, 84, 89, .28);\n  --r-xs: 4px;\n  --r-sm: 5px;\n  --r-md: 16px;\n  --r-lg: 18px;\n  --r-xl: 22px;\n  --r-pill: 9999px;\n  --flare: 20px;\n  --font: 'Inter', system-ui, sans-serif;\n  --maxw: 1320px;\n  --pad: clamp(18px, 3cqi, 22px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--t1);\n  font-family: var(--font);\n  font-variant-numeric: tabular-nums;\n  font-size: 14.5px;\n  line-height: 1.65;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n  padding-bottom: 60px;\n}\n.own-aurora *, .own-aurora *::before, .own-aurora *::after { box-sizing: border-box; }\n.own-aurora a { color: inherit; text-decoration: none; }\n.own-aurora button { font: inherit; cursor: pointer; }\n.own-aurora :focus-visible { outline: 2px solid var(--deep-slate); outline-offset: 2px; border-radius: 6px; }\n.own-aurora .au-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── topbar: brand OUTSIDE the pill, pill starts at nav items ─────────────── */\n.own-aurora .au-topbar { position: sticky; top: 68px; z-index: 40; display: flex; align-items: center; gap: 16px; max-width: var(--maxw); margin: 0 auto; padding: 18px var(--pad) 0; }\n.own-aurora .au-brand { display: flex; align-items: center; gap: 12px; flex: none; }\n.own-aurora .au-mark { display: grid; place-items: center; width: 54px; height: 54px; border-radius: var(--r-md); background: #0E2230; box-shadow: 0 6px 18px -8px rgba(14, 34, 48, .55); }\n.own-aurora .au-mark svg { width: 30px; height: 30px; }\n.own-aurora .au-mark svg rect { fill: #7FD4FF; transform-box: fill-box; transform-origin: center bottom; animation: au-eq 2.6s ease-in-out infinite; }\n.own-aurora .au-mark svg rect:nth-child(1) { animation-delay: 0s; }\n.own-aurora .au-mark svg rect:nth-child(2) { animation-delay: .35s; }\n.own-aurora .au-mark svg rect:nth-child(3) { fill: #E8434A; animation-delay: .7s; }\n.own-aurora .au-mark svg rect:nth-child(4) { animation-delay: .15s; }\n@keyframes au-eq { 0%, 100% { transform: scaleY(1); } 50% { transform: scaleY(.55); } }\n.own-aurora .au-brand-text { display: grid; line-height: 1.05; }\n.own-aurora .au-brand-text b { font-size: 25px; font-weight: 700; letter-spacing: -.035em; color: var(--t0); }\n.own-aurora .au-brand-text em { font-style: normal; font-size: 10.5px; font-weight: 600; letter-spacing: .19em; text-transform: uppercase; color: var(--t3); }\n.own-aurora .au-navbar { flex: 1; display: flex; align-items: center; gap: 4px; padding: 8px 9px; border-radius: var(--r-pill); background: rgba(255, 255, 255, .62); border: 1px solid rgba(255, 255, 255, .7); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); box-shadow: var(--shadow); }\n.own-aurora .au-nav-item { display: inline-flex; align-items: center; gap: 7px; padding: 9px 17px; border-radius: var(--r-pill); font-size: 13.5px; font-weight: 500; color: var(--t2); }\n.own-aurora .au-nav-item .au-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--pale-blue); }\n.own-aurora .au-nav-item:hover { color: var(--t0); }\n.own-aurora .au-nav-item.on { background: var(--deep-slate); color: #fff; }\n.own-aurora .au-nav-item.on .au-dot { background: var(--yellow); }\n.own-aurora .au-nav-spacer { flex: 1; }\n.own-aurora .au-chip { display: inline-flex; align-items: center; padding: 6px 12px; border-radius: var(--r-pill); border: 1px solid var(--line); background: rgba(255, 255, 255, .6); font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--t2); }\n.own-aurora .au-chip-fill { background: var(--mint); border-color: transparent; color: var(--on-mint-fill); }\n.own-aurora .au-btn { display: inline-flex; align-items: center; justify-content: center; padding: 9px 19px; border: 1px solid transparent; border-radius: var(--r-pill); font-size: 13.5px; font-weight: 600; color: #fff; }\n.own-aurora .au-btn-dark { background: var(--deep-slate); }\n.own-aurora .au-btn-dark:hover { background: var(--t0); }\n.own-aurora .au-btn-ghost { background: rgba(255, 255, 255, .7); border-color: var(--line); color: var(--t1); }\n.own-aurora .au-btn-ghost:hover { background: #fff; border-color: rgba(66, 84, 89, .22); }\n.own-aurora .au-identity { display: inline-flex; align-items: center; gap: 8px; padding: 4px 13px 4px 4px; border-radius: var(--r-pill); border: 1px solid var(--line); background: rgba(255, 255, 255, .7); }\n.own-aurora .au-identity:hover { background: #fff; border-color: rgba(66, 84, 89, .22); }\n.own-aurora .au-identity-av { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--deep-slate); color: #fff; font-size: 11px; font-weight: 600; }\n.own-aurora .au-identity-text { display: grid; line-height: 1.25; text-align: left; }\n.own-aurora .au-identity-text b { font-size: 12.5px; font-weight: 600; color: var(--t0); }\n.own-aurora .au-identity-text em { font-style: normal; font-size: 9.5px; font-weight: 600; letter-spacing: .11em; text-transform: uppercase; color: var(--t3); }\n.own-aurora .au-identity svg { width: 15px; height: 15px; color: var(--t3); }\n\n/* ── hero: aurora mesh + oversized 200-weight uppercase headline ──────────── */\n.own-aurora .au-hero { position: relative; max-width: var(--maxw); margin: 0 auto; padding: 64px 8px 44px; display: grid; grid-template-columns: 1.02fr .98fr; gap: 40px; align-items: center; }\n.own-aurora .au-aurora { position: absolute; inset: -60px -40px auto -40px; height: 520px; z-index: 0; pointer-events: none; filter: blur(28px); opacity: .9; background:\n  radial-gradient(38% 46% at 18% 24%, rgba(155, 241, 180, .85), transparent 70%),\n  radial-gradient(34% 42% at 70% 12%, rgba(255, 255, 127, .8), transparent 72%),\n  radial-gradient(40% 50% at 88% 40%, rgba(152, 197, 209, .8), transparent 74%),\n  radial-gradient(30% 40% at 46% 62%, rgba(255, 255, 255, .9), transparent 70%); }\n.own-aurora .au-hero-copy { position: relative; z-index: 1; }\n.own-aurora .au-eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .2em; text-transform: uppercase; color: var(--t3); margin-bottom: 14px; }\n.own-aurora .au-metric { display: flex; align-items: center; gap: 16px; margin-bottom: 8px; }\n.own-aurora .au-metric-num { font-size: clamp(52px, 8cqi, 84px); font-weight: 200; line-height: 1; letter-spacing: -.04em; color: var(--t0); }\n.own-aurora .au-metric-unit { font-size: 30px; font-weight: 300; color: var(--t2); }\n.own-aurora .au-delta { display: inline-flex; align-items: center; gap: 6px; padding: 7px 14px; border-radius: var(--r-pill); background: var(--mint); color: var(--on-mint-fill); font-size: 13.5px; font-weight: 600; }\n.own-aurora .au-delta svg { width: 13px; height: 13px; fill: currentColor; }\n.own-aurora .au-h1 { font-size: clamp(38px, 5.6cqi, 58px); font-weight: 200; line-height: 1.03; letter-spacing: -.028em; text-transform: uppercase; color: var(--t0); margin: 6px 0 18px; }\n.own-aurora .au-accent { font-weight: 400; }\n.own-aurora .au-brief { max-width: 46ch; font-size: 14.5px; font-weight: 400; color: var(--t2); }\n.own-aurora .au-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 26px; }\n.own-aurora .au-hero-cta .au-btn { padding: 12px 26px; }\n\n/* glass trend card */\n.own-aurora .au-card { background: var(--card); border: 1px solid rgba(255, 255, 255, .8); border-radius: var(--r-xl); padding: 22px 24px; box-shadow: var(--shadow); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); }\n.own-aurora .au-trend { position: relative; z-index: 1; display: grid; gap: 14px; }\n.own-aurora .au-trend-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }\n.own-aurora .au-card-title { font-size: 17px; font-weight: 600; letter-spacing: -.015em; color: var(--t0); }\n.own-aurora .au-card-sub { font-size: 10px; font-weight: 500; letter-spacing: .06em; text-transform: uppercase; color: var(--t3); }\n.own-aurora .au-chart { width: 100%; height: 150px; }\n.own-aurora .au-legend { display: flex; justify-content: space-between; }\n.own-aurora .au-legend-key { font-size: 10.5px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--t3); }\n\n/* ── folder tabs: recessed strip + flaring active tab ─────────────────────── */\n.own-aurora .au-tabs { position: relative; max-width: var(--maxw); margin: 8px auto 0; padding: 0 var(--pad); }\n.own-aurora .au-tabrow { position: relative; display: flex; align-items: flex-end; gap: 2px; padding-left: 10px; min-height: 64px; }\n.own-aurora .au-strip { position: absolute; left: 0; right: 0; bottom: 0; height: 44px; background: rgba(66, 84, 89, .16); border-radius: var(--r-md) 0 0 0; z-index: 0; }\n.own-aurora .au-strip::before { content: ''; position: absolute; left: calc(-1 * var(--flare)); bottom: 0; width: var(--flare); height: var(--flare); background: radial-gradient(circle at 0 0, transparent var(--flare), rgba(66, 84, 89, .16) calc(var(--flare) + .5px)); }\n.own-aurora .au-tab { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 8px; padding: 13px 24px; border: 0; background: transparent; border-radius: var(--r-md) var(--r-md) 0 0; font-size: 14.5px; font-weight: 500; color: var(--t2); white-space: nowrap; }\n.own-aurora .au-tab .au-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--slate); }\n.own-aurora .au-tab:hover { color: var(--t0); }\n.own-aurora .au-tab.on { z-index: 3; padding: 21px 32px; margin-bottom: -1px; background: var(--card-2); color: var(--t0); font-weight: 600; }\n.own-aurora .au-tab.on .au-dot { background: var(--accent-dot-green); box-shadow: 0 0 0 3.5px rgba(63, 191, 122, .2); }\n.own-aurora .au-tab.on::before { content: ''; position: absolute; left: calc(-1 * var(--flare)); bottom: 0; width: var(--flare); height: var(--flare); background: radial-gradient(circle at 0 0, transparent var(--flare), var(--card-2) calc(var(--flare) + .5px)); }\n.own-aurora .au-tab.on::after { content: ''; position: absolute; right: calc(-1 * var(--flare)); bottom: 0; width: var(--flare); height: var(--flare); background: radial-gradient(circle at 100% 0, transparent var(--flare), var(--card-2) calc(var(--flare) + .5px)); }\n\n.own-aurora .au-panel { position: relative; z-index: 2; background: var(--card-2); border-radius: var(--r-xl); border-top-left-radius: 0; padding: 24px 26px; box-shadow: var(--shadow); margin-top: -1px; }\n.own-aurora .au-view { display: grid; gap: 6px; }\n.own-aurora .au-view[hidden] { display: none; }\n\n/* wall */\n.own-aurora .au-wall-head, .own-aurora .au-wall-row { display: grid; grid-template-columns: 170px 1fr 92px 118px; gap: 14px; align-items: center; }\n.own-aurora .au-wall-head span, .own-aurora .au-board-head span, .own-aurora .au-city-head span { font-size: 10px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--t3); }\n.own-aurora .au-wall-head, .own-aurora .au-board-head, .own-aurora .au-city-head { padding-bottom: 8px; border-bottom: 1px solid var(--line-2); margin-bottom: 6px; }\n.own-aurora .au-wall-row { padding: 9px 0; border-bottom: 1px solid var(--line-2); }\n.own-aurora .au-wall-name { font-size: 13.5px; font-weight: 500; color: var(--t1); }\n.own-aurora .au-wall-name em { display: block; font-style: normal; font-size: 10px; font-weight: 500; letter-spacing: .06em; text-transform: uppercase; color: var(--t3); }\n.own-aurora .au-heat { display: grid; grid-template-columns: repeat(14, 1fr); gap: 3px; }\n.own-aurora .au-cell { height: 30px; border-radius: var(--r-sm); }\n.own-aurora .au-cur { font-size: 15px; font-weight: 600; }\n.own-aurora .au-bar-wrap { position: relative; height: 7px; border-radius: var(--r-sm); background: var(--progress-track); }\n.own-aurora .au-bar { position: absolute; inset: 0 auto 0 0; border-radius: var(--r-sm); }\n.own-aurora .au-tick { position: absolute; top: -3px; bottom: -3px; left: 71%; width: 1.5px; background: var(--slate); }\n\n/* leaderboard + city rows */\n.own-aurora .au-board-head, .own-aurora .au-board-row { display: grid; grid-template-columns: 26px minmax(90px, 1fr) 1.1fr 58px 54px; gap: 12px; align-items: center; }\n.own-aurora .au-board-row { padding: 10px 0; border-bottom: 1px solid var(--line-2); }\n.own-aurora .au-rank { font-size: 12.5px; font-weight: 600; color: var(--t3); }\n.own-aurora .au-row-name { font-size: 12.5px; font-weight: 500; color: var(--t1); }\n.own-aurora .au-row-val { font-size: 12.5px; font-weight: 600; }\n.own-aurora .au-city-head, .own-aurora .au-city-row { display: grid; grid-template-columns: 1fr 1.1fr 52px 44px; gap: 12px; align-items: center; }\n.own-aurora .au-city-row { padding: 10px 0; border-bottom: 1px solid var(--line-2); }\n.own-aurora .au-q { display: grid; place-items: center; padding: 4px 0; border-radius: 6px; font-size: 9.5px; font-weight: 600; letter-spacing: .06em; }\n.own-aurora .au-q1 { background: var(--mint); color: var(--on-mint-fill); }\n.own-aurora .au-q23 { background: rgba(66, 84, 89, .07); color: var(--t2); }\n.own-aurora .au-q4 { background: rgba(224, 113, 74, .16); color: var(--coral-ink); }\n\n/* region cards */\n.own-aurora .au-regions { max-width: var(--maxw); margin: 22px auto 0; padding: 0 var(--pad); }\n.own-aurora .au-panel-title { font-size: 17px; font-weight: 600; letter-spacing: -.015em; color: var(--t0); margin-bottom: 14px; }\n.own-aurora .au-region-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }\n.own-aurora .au-region { display: grid; gap: 10px; padding: 22px 24px; border-radius: var(--r-xl); background: var(--card); border: 1px solid rgba(255, 255, 255, .8); box-shadow: var(--shadow); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); }\n.own-aurora .au-region-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }\n.own-aurora .au-region-name { font-size: 13.5px; font-weight: 500; color: var(--t1); }\n.own-aurora .au-region-pill { display: inline-flex; align-items: center; padding: 4px 10px; border-radius: var(--r-pill); background: var(--mint); color: var(--on-mint-fill); font-size: 10px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }\n.own-aurora .au-region-num { font-size: 34px; font-weight: 200; letter-spacing: -.03em; }\n.own-aurora .au-region-sub { font-size: 10px; font-weight: 500; letter-spacing: .06em; text-transform: uppercase; color: var(--t3); }\n\n/* note band */\n.own-aurora .au-note-band { max-width: var(--maxw); margin: 22px auto 0; padding: 0 var(--pad); display: grid; grid-template-columns: 1.6fr 1fr; gap: 16px; }\n.own-aurora .au-note-card { background: rgba(246, 250, 248, .7); border-radius: var(--r-lg); padding: 22px 24px; }\n.own-aurora .au-note-card .au-card-title { margin-bottom: 8px; }\n.own-aurora .au-footnote { font-size: 12.5px; font-weight: 400; color: var(--t2); line-height: 1.75; }\n.own-aurora .au-note-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }\n.own-aurora .au-note-stat { display: grid; gap: 4px; align-content: center; padding: 20px 12px; border-radius: var(--r-lg); background: rgba(255, 255, 255, .82); border: 1px solid rgba(255, 255, 255, .8); box-shadow: var(--shadow); text-align: center; }\n.own-aurora .au-note-stat b { font-size: 26px; font-weight: 200; letter-spacing: -.03em; color: var(--mint-ink); }\n.own-aurora .au-note-stat span { font-size: 10px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--t3); }\n\n/* footer */\n.own-aurora .au-footer { max-width: var(--maxw); margin: 34px auto 0; padding: 24px var(--pad) 0; border-top: 1px solid var(--line-2); display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: wrap; }\n.own-aurora .au-footer-brand { display: flex; align-items: center; gap: 14px; }\n.own-aurora .au-mark-lg { width: 54px; height: 54px; border-radius: var(--r-xl); }\n.own-aurora .au-footer-brand b { font-size: 18px; font-weight: 700; letter-spacing: -.03em; color: var(--t0); }\n.own-aurora .au-footer-links { display: flex; gap: 20px; font-size: 13.5px; font-weight: 500; color: var(--t2); }\n.own-aurora .au-footer-links a:hover { color: var(--t0); }\n\n/* ── responsive (source's single 1080px breakpoint) ───────────────────────── */\n@container frame (max-width: 1080px) {\n  .own-aurora .au-hero { grid-template-columns: 1fr; gap: 28px; }\n  .own-aurora .au-region-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-aurora .au-h1 { font-size: 40px; }\n  .own-aurora .au-metric-num { font-size: 60px; }\n  .own-aurora .au-note-band { grid-template-columns: 1fr; }\n  .own-aurora .au-nav-item, .own-aurora .au-nav-spacer, .own-aurora .au-chip { display: none; }\n  .own-aurora .au-navbar { flex: 1; justify-content: flex-end; }\n}\n@container frame (max-width: 760px) {\n  .own-aurora .au-topbar { top: 0; flex-wrap: wrap; padding: 12px 14px 0; }\n  .own-aurora .au-brand-text em { display: none; }\n  .own-aurora .au-identity-text { display: none; }\n  .own-aurora .au-hero { padding: 36px 14px 28px; }\n  .own-aurora .au-tabs, .own-aurora .au-regions, .own-aurora .au-note-band, .own-aurora .au-footer { padding-left: 14px; padding-right: 14px; }\n  .own-aurora .au-tabrow { overflow-x: auto; scrollbar-width: none; }\n  .own-aurora .au-tabrow::-webkit-scrollbar { display: none; }\n  .own-aurora .au-tab { padding: 12px 16px; font-size: 13.5px; }\n  .own-aurora .au-tab.on { padding: 18px 20px; }\n  .own-aurora .au-wall-head { display: none; }\n  .own-aurora .au-wall-row { grid-template-columns: 1fr auto; gap: 8px 12px; }\n  .own-aurora .au-wall-row .au-heat { grid-column: 1 / -1; grid-row: 2; }\n  .own-aurora .au-wall-row .au-bar-wrap { display: none; }\n  .own-aurora .au-board-head, .own-aurora .au-board-row { grid-template-columns: 22px 1fr 52px 40px; }\n  .own-aurora .au-board-head span:nth-child(3), .own-aurora .au-board-row > *:nth-child(3) { display: none; }\n  .own-aurora .au-city-head, .own-aurora .au-city-row { grid-template-columns: 1fr 44px 40px; }\n  .own-aurora .au-city-head span:nth-child(2), .own-aurora .au-city-row > *:nth-child(2) { display: none; }\n}\n@container frame (max-width: 430px) {\n  .own-aurora .au-metric { flex-wrap: wrap; }\n  .own-aurora .au-panel { padding: 18px 16px; }\n  .own-aurora .au-note-stats { grid-template-columns: 1fr 1fr 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-aurora *, .own-aurora *::before, .own-aurora *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n  .own-aurora .au-mark svg rect { animation: none !important; }\n}\n"};
/* ══ NORTHWIND — Aurora-language performance wall for showcase.html ═════════
   Registers window.OWN_LAYOUTS['aurora'].init(root). Renders the KPI wall,
   leaderboard, and city table from one data set, wires the folder tabs, and
   returns a cleanup that detaches every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  /* 14-day heat states: 'down' | 'mid' | 'up' | 'none'. Deterministic sample. */
  var METRICS = [
    { name: 'Throughput', sub: 'Units / day', seed: 1, today: 98.1, goal: 96 },
    { name: 'Line yield', sub: 'Passing grade', seed: 2, today: 94.6, goal: 95 },
    { name: 'On-time', sub: 'Shipments', seed: 3, today: 97.2, goal: 96 },
    { name: 'Cost / unit', sub: 'Indexed', seed: 4, today: 91.8, goal: 94 },
    { name: 'Fulfilment', sub: 'First touch', seed: 5, today: 99.1, goal: 97 },
    { name: 'Utilisation', sub: 'Line hours', seed: 6, today: 88.4, goal: 90 }
  ];
  var REGIONS = [
    { name: 'Luzon', ptg: 102.4, q: 1 },
    { name: 'Busan', ptg: 100.8, q: 1 },
    { name: 'Singapore', ptg: 99.3, q: 2 },
    { name: 'Sydney', ptg: 97.1, q: 2 },
    { name: 'Visayas', ptg: 95.6, q: 3 },
    { name: 'Rotterdam', ptg: 93.2, q: 3 },
    { name: 'Mindanao', ptg: 89.4, q: 4 },
    { name: 'Jakarta', ptg: 86.1, q: 4 }
  ];
  var CITIES = [
    { name: 'Manila', ptg: 101.9, n: 412 },
    { name: 'Busan', ptg: 100.2, n: 288 },
    { name: 'Singapore', ptg: 98.7, n: 344 },
    { name: 'Cebu', ptg: 96.8, n: 176 },
    { name: 'Sydney', ptg: 94.1, n: 221 },
    { name: 'Davao', ptg: 91.3, n: 133 }
  ];

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function heatStates(seed) {
    var out = [], x = seed * 7 + 3;
    for (var i = 0; i < 14; i++) {
      x = (x * 31 + 17) % 100;
      out.push(x < 22 ? 'down' : x < 55 ? 'mid' : x < 90 ? 'up' : 'none');
    }
    return out;
  }
  function inkFor(ptg, goal) { return ptg >= goal ? 'var(--mint-ink)' : ptg >= goal - 3 ? 'var(--amber-ink)' : 'var(--coral-ink)'; }

  OWN['aurora'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }
      function $(s) { return root.querySelector(s); }

      var wall = $('#auWall');
      if (wall) {
        wall.innerHTML = METRICS.map(function (m) {
          var states = heatStates(m.seed).map(function (s) {
            var bg = s === 'down' ? 'rgba(224,113,74,.62)' : s === 'mid' ? 'rgba(255,226,74,.7)' : s === 'up' ? 'rgba(155,241,180,.9)' : 'var(--line-2)';
            return '<span class="au-cell" style="background:' + bg + '"></span>';
          }).join('');
          var pct = Math.min(100, Math.max(6, (m.today / 140) * 100));
          var color = m.today >= m.goal ? 'var(--bar-fill-green)' : m.today >= m.goal - 3 ? 'var(--amber-bar-fill)' : 'var(--coral)';
          return '<div class="au-wall-row">'
            + '<span class="au-wall-name">' + esc(m.name) + '<em>' + esc(m.sub) + '</em></span>'
            + '<span class="au-heat">' + states + '</span>'
            + '<span class="au-cur" style="color:' + inkFor(m.today, m.goal) + '">' + m.today.toFixed(1) + '%</span>'
            + '<span class="au-bar-wrap"><span class="au-bar" style="width:' + pct + '%;background:' + color + '"></span><span class="au-tick"></span></span>'
            + '</div>';
        }).join('');
      }

      var board = $('#auBoard');
      if (board) {
        board.innerHTML = REGIONS.map(function (r, i) {
          var pct = Math.min(100, Math.max(6, (r.ptg / 140) * 100));
          var qc = r.q === 1 ? 'au-q1' : r.q === 4 ? 'au-q4' : 'au-q23';
          return '<div class="au-board-row">'
            + '<span class="au-rank">' + (i + 1) + '</span>'
            + '<span class="au-row-name">' + esc(r.name) + '</span>'
            + '<span class="au-bar-wrap"><span class="au-bar" style="width:' + pct + '%;background:' + (r.ptg >= 100 ? 'var(--bar-fill-green)' : r.ptg >= 95 ? 'var(--amber-bar-fill)' : 'var(--coral)') + '"></span><span class="au-tick"></span></span>'
            + '<span class="au-row-val" style="color:' + inkFor(r.ptg, 100) + '">' + r.ptg.toFixed(1) + '</span>'
            + '<span class="au-q ' + qc + '">Q' + r.q + '</span>'
            + '</div>';
        }).join('');
      }

      var city = $('#auCity');
      if (city) {
        city.innerHTML = CITIES.map(function (c) {
          var pct = Math.min(100, Math.max(6, (c.ptg / 140) * 100));
          return '<div class="au-city-row">'
            + '<span class="au-row-name">' + esc(c.name) + '</span>'
            + '<span class="au-bar-wrap"><span class="au-bar" style="width:' + pct + '%;background:' + (c.ptg >= 100 ? 'var(--bar-fill-green)' : c.ptg >= 95 ? 'var(--amber-bar-fill)' : 'var(--coral)') + '"></span><span class="au-tick"></span></span>'
            + '<span class="au-row-val" style="color:' + inkFor(c.ptg, 100) + '">' + c.ptg.toFixed(1) + '</span>'
            + '<span class="au-q au-q23">' + c.n + '</span>'
            + '</div>';
        }).join('');
      }

      var regions = $('#auRegions');
      if (regions) {
        regions.innerHTML = REGIONS.slice(0, 8).map(function (r) {
          var good = r.ptg >= 100;
          var cls = good ? 'var(--mint-ink)' : r.ptg >= 95 ? 'var(--amber-ink)' : 'var(--coral-ink)';
          var pill = r.ptg >= 100
            ? '<span class="au-region-pill">At goal</span>'
            : '<span class="au-region-pill" style="background:rgba(224,113,74,.16);color:var(--coral-ink)">Below</span>';
          return '<article class="au-region">'
            + '<div class="au-region-top"><span class="au-region-name">' + esc(r.name) + '</span>' + pill + '</div>'
            + '<span class="au-region-num" style="color:' + cls + '">' + r.ptg.toFixed(1) + '</span>'
            + '<span class="au-region-sub">PTG vs goal 100</span>'
            + '</article>';
        }).join('');
      }

      var row = $('#auTabrow');
      on(row, 'click', function (e) {
        var tab = e.target.closest('.au-tab'); if (!tab) return;
        Array.prototype.forEach.call(row.querySelectorAll('.au-tab'), function (t) {
          var on = t === tab;
          t.classList.toggle('on', on);
          t.setAttribute('aria-pressed', String(on));
        });
        Array.prototype.forEach.call(root.querySelectorAll('.au-view'), function (v) {
          v.hidden = v.dataset.view !== tab.dataset.tab;
        });
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
